import random
def _rna():
    rng = random.Random(20260902)
    tx = [f"TX{i:04d}" for i in range(1, 1001)]
    genes = [f"GENE_{i:03d}" for i in range(1, 251)]
    t2g = {t: genes[rng.randrange(len(genes))] for t in tx}
    qa = {t: round(rng.uniform(0, 400), 3) for t in tx}
    qb = {t: round(rng.uniform(0, 400), 3) for t in tx}
