import random
def _k8():
    rng = random.Random(20260902)
    out = {}
    for i in range(1, 151):
        v = {"name": "v1alpha1", "served": True, "storage": rng.random() > 0.1,
             "subresources": {"status": {}} if rng.random() < 0.6 else {},
             "schema": {"openAPIV3Schema": {"type": "object" if rng.random() > 0.1 else "string",
                        "properties": {"spec": {"type": "object"},
                                       "status": {"type": "object", "properties":
                                                  ({"conditions": {"type": "array"}} if rng.random() < 0.5 else {"phase": {"type": "string"}})}}}},
             "additionalPrinterColumns": [{"name": c, "type": "string", "jsonPath": ".status.phase"}
                                          for c in rng.sample(["Age", "Status", "Phase", "Ready"], rng.randrange(0, 3))]}
        if rng.random() < 0.1:
            v["schema"]["openAPIV3Schema"]["x-kubernetes-preserve-unknown-fields"] = True
        names = {"kind": f"Widget{i}", "plural": f"widgets{i}"}
        if rng.random() > 0.15: names["singular"] = f"widget{i}"
        if rng.random() > 0.15: names["listKind"] = f"Widget{i}List"
        out[f"crd_{i:03d}.json"] = {"spec": {"group": "widgets-group", "names": names,
                                              "scope": "Namespaced" if rng.random() > 0.3 else "Cluster",
                                              "versions": [v]}}
    return out

import json, os
os.makedirs("manifests", exist_ok=True)
for name, crd in _k8().items():
    json.dump(crd, open(os.path.join("manifests", name), "w"), indent=1)

