import json
def has_conditions(x):
    if isinstance(x, dict):
        return "conditions" in x.get("properties", {}) or any(has_conditions(v) for v in x.values())
    return False
def checks(c):
    s = c["spec"]; v0 = s["versions"][0]; sch = v0["schema"]["openAPIV3Schema"]
    cols = {x["name"] for x in v0.get("additionalPrinterColumns", [])}
    r = {"status_subresource": "status" in v0.get("subresources", {}),
         "scope_namespaced": s.get("scope") == "Namespaced",
         "names_defined": bool(s["names"].get("singular")) and bool(s["names"].get("listKind")),
         "schema_typed": sch.get("type") == "object" and sch.get("x-kubernetes-preserve-unknown-fields") is not True,
         "served_and_storage": any(v.get("served") and v.get("storage") for v in s["versions"]),
         "conditions_in_schema": has_conditions(sch["properties"].get("status", {})),
         "printer_columns_age_status": "Age" in cols and bool(cols & {"Status", "Phase"})}
    return {k: "PASS" if v else "FAIL" for k, v in r.items()}
d = json.load(open("crd_report.json"))
